import{_ as a}from"./chunks/simd_reg_2.B0ZPuYR5.js";import{_ as r,o as t,a as i,b as o}from"./app.C41L12d5.js";const n="/ascendc.github.io/assets/npu_2201_2.sKIFwsJq.png",s="/ascendc.github.io/assets/npu_3510_2.CHz6GLd3.png",b=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"编程模型","link":"/guide/programming_guide/programming_model/programming_model"},{"text":"AI Core SIMD编程","link":"/guide/programming_guide/programming_model/ai_core_simd_programming/ai_core_simd_programming"},{"text":"抽象硬件架构","link":"/guide/programming_guide/programming_model/ai_core_simd_programming/abstract_hardware_architecture"}]},"headers":[],"relativePath":"guide/programming_guide/programming_model/ai_core_simd_programming/abstract_hardware_architecture.md","filePath":"guide/programming_guide/programming_model/ai_core_simd_programming/abstract_hardware_architecture.md","outlineHeaders":[{"level":2,"title":"概览","slug":"概览","link":"#概览"},{"level":2,"title":"计算单元","slug":"计算单元","link":"#计算单元"},{"level":2,"title":"存储单元和搬运单元","slug":"存储单元和搬运单元","link":"#存储单元和搬运单元"},{"level":2,"title":"执行流程与同步机制","slug":"执行流程与同步机制","link":"#执行流程与同步机制"},{"level":2,"title":"架构版本差异","slug":"架构版本差异","link":"#架构版本差异"}],"lastUpdated":1788515292000}'),_={name:"guide/programming_guide/programming_model/ai_core_simd_programming/abstract_hardware_architecture.md"};function l(g,e,d,c,m,h){return t(),i("div",null,[...e[0]||(e[0]=[o('<div><article class="markdown-body"><h1>抽象硬件架构<span id="ZH-CN_TOPIC_0000001861989988"></span></h1><p>AI Core是AI处理器的计算核心，AI处理器内部有多个AI Core。本章节将介绍AI Core的并行计算架构抽象，该抽象架构屏蔽了不同硬件之间的差异。使用Ascend C进行编程时，基于抽象硬件架构，可以简化硬件细节，显著降低开发门槛。如需了解更详细的硬件架构信息或者原理，请参考<a href="../../advanced_programming/hardware_implementation/basic_architecture.html">硬件实现</a>。</p><h2 id="概览">概览<span id="section_core_components"></span><a class="header-anchor" href="#概览">​</a></h2><p>AI Core的抽象硬件架构可以分为<a href="#section_compute_units"><strong>计算单元</strong></a>、<a href="#section_memory_units"><strong>存储单元</strong></a>、<a href="#section_memory_units"><strong>搬运单元</strong></a>三类核心组件。下图以NPU架构版本2201为例，展示三类组件在AI Core中的位置关系和协同方式。</p><p><strong>图1</strong> 抽象硬件架构（<a href="../../language_extension/simd_builtin_keywords.html#npu-arch">NPU架构版本2201</a>）<span id="fig1095152043812"></span></p><img src="'+n+'" alt="抽象硬件架构" width="840px"><p>结合前述三类组件和<a href="#fig1095152043812">图1</a>，一次算子执行可以理解为三类组件协同完成数据处理的过程：Host侧下发算子任务后，算子指令序列进入Device侧的AI Core；计算单元负责控制逻辑以及标量、矢量和矩阵计算，存储单元保存输入、输出和中间数据，搬运单元负责在不同存储层级之间转移数据。</p><p>需要注意的是，上述过程并不表示各步骤完全串行执行。异构系统中存在Host侧与Device侧之间的异步并行，也存在Device内部不同执行单元之间的流水化并行。后续章节将分别介绍计算单元、存储单元和搬运单元的具体组成，并进一步说明异步执行与同步机制之间的关系。</p><h2 id="计算单元">计算单元<span id="section_compute_units"></span><a class="header-anchor" href="#计算单元">​</a></h2><p>AI Core中的计算单元主要包括Scalar、Vector和Cube三类。</p><p><strong>表1</strong> 计算单元</p><p><span id="zh-cn_topic_0000001588832845_table14884154362"></span></p><table><thead><tr><th>组件名称</th><th>组件功能</th><th>对应编程概念</th></tr></thead><tbody><tr><td>Scalar</td><td>执行地址计算、循环控制等标量计算工作，并把矢量计算、矩阵计算、数据搬运、同步指令发射给对应单元执行。</td><td>核函数（Kernel）中的控制逻辑、同步控制API。</td></tr><tr><td>Vector</td><td>负责执行矢量运算。</td><td>矢量计算API、矢量类算子。</td></tr><tr><td>Cube</td><td>负责执行矩阵运算。</td><td>矩阵计算API、矩阵类算子。</td></tr></tbody></table><h2 id="存储单元和搬运单元">存储单元和搬运单元<span id="section_memory_units"></span><a class="header-anchor" href="#存储单元和搬运单元">​</a></h2><p>存储单元可以从使用位置上分为Local Memory和Global Memory。</p><ul><li><strong>Local Memory</strong>：AI Core片内存储，用于暂存从Global Memory搬入的数据分片，并保存计算输出和中间结果。这些数据可供Vector、Cube等计算单元高效访问，继续参与片内计算，或通过搬运单元搬出到Global Memory。Local Memory包含面向不同编程方式和计算单元的片内资源，如<a href="#fig_simd_reg_memory_hierarchy">图2</a>所示。</li><li><strong>Global Memory</strong>：Device侧全局存储，是Local Memory中数据搬入和搬出的主要来源或目的位置。</li></ul><p><strong>图2</strong> SIMD-Reg矢量计算内存层级<span id="fig_simd_reg_memory_hierarchy"></span></p><img src="'+a+'" alt="SIMD-Reg矢量计算内存层级" width="520px"><p><strong>DMA（Direct Memory Access）搬运单元</strong>负责数据搬运，包括Global Memory和Local Memory之间的数据搬入、搬出，以及不同层级Local Memory之间的数据流转。常见搬运单元包括MTE1、MTE2、MTE3和FixPipe，具体介绍请参考<a href="../../advanced_programming/hardware_implementation/basic_architecture.html#table288493152012">搬运单元</a>。</p><h2 id="执行流程与同步机制">执行流程与同步机制<span id="section_programming_flow"></span><a class="header-anchor" href="#执行流程与同步机制">​</a></h2><p>理解抽象硬件架构时，还需要关注不同单元如何协同完成一次数据块处理。可以从<strong>异步指令流、同步信号流、计算数据流</strong>三个视角理解：</p><ul><li><strong>异步指令流</strong>：表示Scalar计算单元对其他执行单元的任务发射关系，而不是完整指令执行流程。Scalar计算单元根据算子指令序列，将计算、搬运等任务发射到Vector、Cube、DMA等单元的指令队列中，各执行单元再在各自流水上异步执行。该过程可以参考<a href="#fig1095152043812">图1</a>所示的指令流。</li><li><strong>计算数据流</strong>：表示各执行单元在指令控制下访问或更新存储资源的关系，而不是一次计算任务中完整的数据搬入、计算、搬出流程。例如，Vector/Cube等计算单元基于Local Memory中的数据执行计算，DMA搬运单元负责Local Memory和Global Memory之间的数据流转。该过程可以参考<a href="#fig1095152043812">图1</a>所示的数据流。</li><li><strong>同步信号流</strong>：表示Scalar计算单元通过同步信号约束不同执行单元任务先后关系的控制路径，而不是数据本身的流向。当不同单元的异步任务存在数据依赖或顺序依赖时，需要通过同步信号约束执行先后。该过程可以参考<a href="#fig1095152043812">图1</a>所示的同步信号流。</li></ul><p>因此，开发者不仅要关注数据如何搬入、计算和搬出，还需要理解同步机制如何保证异步任务按正确的依赖关系执行。同步控制相关接口及依赖关系在编程中的表达方式，请参考<a href="../../../../api/SIMD-API/basic_api/sync_control/intra_core_sync/intra_core_sync_overview.html">核内同步能力概述</a>。</p><h2 id="架构版本差异">架构版本差异<span id="section_arch_version"></span><a class="header-anchor" href="#架构版本差异">​</a></h2><p><strong>图3</strong> 抽象硬件架构（<a href="../../language_extension/simd_builtin_keywords.html#npu-arch">NPU架构版本3510</a>）<span id="fig10951520438120"></span></p><img src="'+s+'" alt="抽象硬件架构NPU架构版本3510" width="840px"><p>与NPU架构版本2201相比，NPU架构版本3510的主要差异如下：</p><ul><li>新增<a href="c_pointer_programming/reg_vector_computation.html">Regbase矢量计算方式</a>，支持直接使用寄存器参与计算。Membase和Regbase的差异见下表。</li><li>计算单元、存储单元和数据类型支持范围存在差异，具体请参考<a href="../../../cross_gen_migration_guide/3510_arch_migration/2201_to_3510_arch_changes.html#section_2201_to_3510_storage_unit_changes">存储单元变更</a>和<a href="../../../../api/SIMD-API/basic_api/data_structures/builtin_data_types.html">内置数据类型</a>。</li><li>编程方式更加丰富，除SIMD编程外，还支持SIMT编程以及SIMD与SIMT混合编程。三种编程方式的选择指导请参见<a href="../programming_model_overview.html#section_ai_core_programming_model">AI Core编程模型</a>。</li></ul><p><strong>表2</strong> Membase和Regbase差异</p><table><thead><tr><th>计算方式</th><th>数据暂存位置</th><th>特点</th><th>适用场景</th></tr></thead><tbody><tr><td>Membase</td><td>Local Memory（UB）</td><td>每步计算结果写回UB</td><td>NPU架构版本2201</td></tr><tr><td>Regbase</td><td>寄存器（VF Reg）</td><td>中间结果可暂存寄存器，减少UB读写</td><td>NPU架构版本3510</td></tr></tbody></table><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><ul><li>不同产品型号和NPU架构版本的对应关系请参考<a href="../../language_extension/simd_builtin_keywords.html#npu-arch"><strong>NPU_ARCH</strong></a>。</li><li>详细架构变更请参考<a href="../../../cross_gen_migration_guide/3510_arch_migration/2201_to_3510_arch_changes.html">2201到3510架构变更</a>。</li></ul></div></article></div>',1)])])}const f=r(_,[["render",l]]);export{b as __pageData,f as default};
